      const ring = Lr.slice(), cap = (cx, cy, ux, uy, hw) => { for (let k = 1; k < 6; k++) { const t = k / 6 * Math.PI, c = Math.cos(t), s = Math.sin(t); ring.push(cx + (ux * c + uy * s) * hw, cy + (uy * c - ux * s) * hw); } };
