      const o = { part, fill, stroke, sw, op, brush: fl.indexOf('b') >= 0, grad: fl.indexOf('g') >= 0, pupil: fl.indexOf('p') >= 0, led: fill === '#39e07a' };
      const amp = fl.indexOf('r') >= 0 ? 1.15 : fl.indexOf('s') >= 0 ? 0.45 : 0;
